-- Seed the fictional 100-sponsor pool from Pool Sponsor v1.1 (source file).
-- Budget envelope = listed annual contract value multiplied by listed duration.
alter table public.caleris_sponsors
 add column if not exists source_code text,
 add column if not exists default_duration_seasons integer not null default 1 check(default_duration_seasons between 1 and 5),
 add column if not exists is_indonesian boolean not null default false,
 add column if not exists focus_key text;
create unique index if not exists caleris_sponsors_source_code_unique on public.caleris_sponsors(source_code) where source_code is not null;

on conflict(tier_key) do update set label=excluded.label,minimum_team_reputation=excluded.minimum_team_reputation,is_active=true,updated_at=now();

on conflict(config_key) do update set config_value=excluded.config_value,description=excluded.description,updated_at=now();

on conflict(source_code) where source_code is not null do update set
 name=excluded.name,industry=excluded.industry,industry_category=excluded.industry_category,tier_key=excluded.tier_key,
 available_budget=greatest(public.caleris_sponsors.available_budget,excluded.available_budget),
 target_audience=excluded.target_audience,default_duration_seasons=excluded.default_duration_seasons,
 is_indonesian=excluded.is_indonesian,focus_key=excluded.focus_key,updated_at=now();

